create or replace function public.lookup_payee_account(p_account_number text) returns table(id uuid,name text,account_number text) language plpgsql stable security definer set search_path=public as $$ begin if auth.uid() is null or not exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='active') then raise exception 'Active membership required'; end if; if length(trim(coalesce(p_account_number,'')))<8 or length(trim(p_account_number))>32 then raise exception 'Invalid account number'; end if; return query select a.id,a.name,a.account_number from public.bank_accounts a where a.account_number=upper(trim(p_account_number)) and a.status='active' and a.kind<>'treasury' limit 1; end $$; revoke all on function public.lookup_payee_account(text) from public,anon,authenticated; grant execute on function public.lookup_payee_account(text) to authenticated;